//! Story 128.3 P0 ATDD: independent per-source IRQ state and real RTL execution.
//! Missing Irq import is interface RED only; the oracle is not extracted from HIR.
use bitloom_prelude::{Elaboratable, FrozenHir, ip::Irq};
use std::{collections::BTreeMap, fmt::Write as _, fs, path::Path, process::{Command, Stdio}};

#[derive(Clone, Copy, Debug, Default)]
struct Input { rst: bool, valid: bool, write: bool, addr: u16, data: u32, strb: u8, ready: bool, raw: u8 }
#[derive(Clone, Copy, Debug)]
struct Response { data: u32, error: u32 }
#[derive(Default)]
struct Oracle {
    latched: [bool; 5], enabled: [bool; 5], response: Option<Response>,
    accepted: usize, consumed: usize, cancelled: usize,
    hw: [usize; 5], test: [usize; 5], collisions: [usize; 5],
    strobes: [[usize; 16]; 3], raw_reads: [usize; 32],
}
type Values = BTreeMap<&'static str, u64>;
struct Frame { i: Input, before: Values, after: Values }
fn word(bits: &[bool; 5]) -> u32 { bits.iter().enumerate().map(|(n,b)| u32::from(*b) << n).sum() }
impl Oracle {
    fn commit(&self, i: Input) -> bool { !i.rst && self.response.is_none() && i.valid }
    fn outputs(&self, i: Input) -> Values {
        let mut v = Values::from([
            ("req_ready", u64::from(!i.rst && self.response.is_none())),
            ("rsp_valid", u64::from(self.response.is_some())),
            ("irq", u64::from((0..5).any(|n| self.latched[n] && self.enabled[n]))),
        ]);
        if let Some(r) = self.response { v.insert("rdata", r.data.into()); v.insert("error", r.error.into()); }
        v
    }
    fn frame(&mut self, i: Input) -> Frame {
        assert!(i.raw < 32 && i.strb < 16);
        let before = self.outputs(i);
        if i.rst {
            self.cancelled += usize::from(self.response.is_some());
            self.latched.fill(false); self.enabled.fill(false); self.response = None;
        } else {
            let commit = self.commit(i);
            let write_allowed = commit && i.write && matches!(i.addr, 0 | 4 | 8);
            let selected = write_allowed && i.strb & 1 != 0;
            if commit {
                // Read the old abstract state before applying this edge's events.
                let read = match i.addr { 0 => Some(word(&self.latched)), 4 => Some(word(&self.enabled)), 12 => Some(i.raw.into()), _ => None };
                let legal = if i.write { matches!(i.addr, 0 | 4 | 8) } else { read.is_some() };
                self.response = Some(Response { data: if !i.write && legal { read.unwrap() } else { 0 }, error: if legal { 0 } else { 2 } });
                self.accepted += 1;
                if write_allowed { self.strobes[(i.addr / 4) as usize][i.strb as usize] += 1; }
                if !i.write && i.addr == 12 { self.raw_reads[i.raw as usize] += 1; }
            } else if self.response.is_some() && i.ready { self.response = None; self.consumed += 1; }
            // Independent event-list oracle: clear one source, then deliver events.
            // There is no DUT bit-vector next-state expression or descriptor dependency.
            for source in 0..5 {
                let software_bit = i.data & (1 << source) != 0;
                let hardware = i.raw & (1 << source) != 0;
                if selected && i.addr == 4 { self.enabled[source] = software_bit; }
                if selected && i.addr == 0 && software_bit {
                    self.latched[source] = false;
                    if hardware { self.collisions[source] += 1; }
                }
                if selected && i.addr == 8 && software_bit { self.latched[source] = true; self.test[source] += 1; }
                if hardware { self.latched[source] = true; self.hw[source] += 1; }
            }
        }
        assert_eq!(self.accepted, self.consumed + self.cancelled + usize::from(self.response.is_some()));
        Frame { i, before, after: self.outputs(i) }
    }
}
#[derive(Default)]
struct Trace { m: Oracle, frames: Vec<Frame>, tags: BTreeMap<&'static str, usize> }
impl Trace {
    fn step(&mut self, i: Input) { self.frames.push(self.m.frame(i)); }
    fn mark(&mut self, tag: &'static str) { *self.tags.entry(tag).or_default() += 1; }
    fn reset(&mut self) { self.step(Input { rst: true, ..Input::default() }); }
    fn request(&mut self, i: Input, stall: usize) {
        assert!(self.m.response.is_none());
        self.step(Input { valid: true, ..i });
        for _ in 0..stall { self.step(Input::default()); }
        self.step(Input { ready: true, ..Input::default() });
    }
    fn write(&mut self, addr: u16, data: u32, strb: u8) { self.request(Input { write: true, addr, data, strb, ..Input::default() }, 0); }
    fn read(&mut self, addr: u16) { self.request(Input { addr, ..Input::default() }, 0); }
    fn inspect(&mut self) { for addr in [0,4,12] { self.read(addr); } }
}
fn random(seed: &mut u64) -> u32 { *seed ^= *seed << 13; *seed ^= *seed >> 7; *seed ^= *seed << 17; *seed as u32 }
fn trace(seed0: u64) -> Trace {
    let mut t = Trace::default(); t.reset(); t.inspect();
    // Exhaust every hardware event word against every enable word. Pending is read
    // back, so an implementation that masks at event capture is observable.
    for raw in 0..32 {
        for mask in 0..32 {
            t.reset(); t.write(4, mask, 1);
            t.step(Input { raw, ..Input::default() }); assert_eq!(word(&t.m.latched),u32::from(raw)); t.read(0);
            t.write(4, 0, 1); t.read(0); t.write(4, 31, 1);
            t.request(Input { addr: 12, raw, ..Input::default() }, 3);
            t.inspect(); t.mark("all_source_mask_pairs");
        }
    }
    // All byte strobes, all writable registers, zero / valid / reserved bits.
    for addr in [0,4,8] { for strb in 0..16 { for data in [0,31,0xffff_ffe0,0xffff_ffff,0x805a_0015] {
        t.reset(); t.write(4,31,1); t.write(8,31,1);
        t.write(addr,data,strb); t.inspect(); t.mark("all_wstrb_register_patterns");
    } } }
    for source in 0..5 {
        let bit = 1u8 << source;
        t.reset(); t.step(Input { raw: bit, ..Input::default() });
        t.read(0); t.write(4,bit.into(),1); t.mark("disabled_capture_then_enable");
        // Repetition is sticky, not a counter: one clear removes all past pulses.
        for _ in 0..4 { t.step(Input { raw: bit, ..Input::default() }); }
        t.write(0,bit.into(),1); t.inspect(); t.mark("repeat_not_counted");
        // Consecutive high cycles still supply events, including the clear edge.
        t.step(Input { raw: bit, ..Input::default() });
        t.request(Input { write:true, addr:0, data:bit.into(), strb:1, raw:bit, ..Input::default() }, 2);
        t.read(0); t.mark("same_source_clear_collision");
        t.request(Input { write:true, addr:0, data:bit.into(), strb:1, raw:1 << ((source+1)%5), ..Input::default() },0);
        t.read(0); t.mark("other_source_clear_collision");
        t.write(0,31,1); t.request(Input { write:true, addr:8, data:bit.into(), strb:1, raw:bit, ..Input::default() },2);
        t.inspect(); t.mark("same_source_test_hardware");
        t.write(0,31,1); t.request(Input { write:true, addr:8, data:bit.into(), strb:1, raw:1 << ((source+1)%5), ..Input::default() },2);
        t.inspect(); t.mark("other_source_test_hardware");
        // Request edge captures OLD pending, but its hardware event is visible later.
        t.write(0,31,1); t.request(Input { addr:0, raw:bit, ..Input::default() },2); t.read(0);
        t.mark("pending_old_snapshot");
        t.write(0,31,1); t.request(Input { addr:12, raw:bit, ..Input::default() },5); t.inspect();
        t.mark("raw_snapshot_stall");
        t.write(0,31,1); t.write(8,bit.into(),1); t.read(12); t.read(0); t.mark("test_excluded_from_raw");
    }
    // Idle TEST candidates must never become events.
    t.reset(); t.write(4,31,1);
    for strb in 0..16 { t.step(Input { addr:8, write:true, data:u32::MAX, strb, ..Input::default() }); t.inspect(); t.mark("idle_test_candidate"); }
    // Queue a held TEST behind a read response. It cannot commit on the consume
    // edge, and cannot turn into events until the following available cycle.
    t.reset(); t.write(4,31,1);
    t.step(Input { valid:true, addr:0, ..Input::default() });
    let held = Input { valid:true, write:true, addr:8, data:1, strb:1, ..Input::default() };
    for _ in 0..5 { t.step(held); }
    t.step(Input { ready:true, ..held }); t.step(held);
    // Keep its committed request payload visible while stalling the response.
    for _ in 0..5 { t.step(Input { addr:8, write:true, data:1, strb:1, ..Input::default() }); }
    t.step(Input { ready:true, ..Input::default() }); t.write(0,31,1); t.inspect();
    t.mark("held_test_and_consume_no_refill");
    // Changes in RAW during a stalled response must neither alter the snapshot
    // nor prevent hardware event capture.
    t.reset(); t.write(4,31,1);
    t.step(Input { valid:true, addr:12, raw:1, ..Input::default() });
    for source in 1..5 { t.step(Input { raw:1 << source, ..Input::default() }); }
    t.step(Input { ready:true, ..Input::default() }); t.inspect(); t.mark("backpressure_accepts_hardware");
    // Permission wins even with WSTRB zero; addresses are never truncated.
    for addr in [0,4,8,12,1,2,3,5,9,13,16,0x300,0x304,0x8000,0xfffc,0xffff] {
        for write in [false,true] { for strb in [0,1,15] {
            t.reset(); t.write(4,31,1);
            t.request(Input { addr,write,data:u32::MAX,strb,raw:16,..Input::default() },2);
            t.inspect(); t.mark("permissions_holes_aliases_with_hardware");
        } }
    }
    // Cancel both read and write responses, with valid TEST/clear and events at
    // reset. No stale response or reset-edge event may escape afterwards.
    for addr in [0,8,12] { for write in [false,true] {
        t.reset(); t.write(4,31,1); t.write(8,31,1);
        t.step(Input { valid:true,addr,write,data:31,strb:1,..Input::default() });
        t.step(Input { raw:31,..Input::default() });
        t.step(Input { rst:true,valid:true,addr:8,write:true,data:31,strb:1,raw:31,..Input::default() });
        t.inspect(); t.step(Input { raw:1,..Input::default() }); t.inspect(); t.mark("reset_cancels_stalled_response");
    } }
    for addr in [0,8] {
        t.reset(); t.write(4,31,1); t.write(8,31,1);
        t.step(Input { rst:true,valid:true,write:true,addr,data:31,strb:1,raw:31,..Input::default() });
        t.inspect(); t.mark("reset_beats_available_commit");
    }
    let mut seed=seed0; let mut held:Option<Input>=None;
    for n in 0..3200 {
        if held.is_none() && random(&mut seed)&3 != 0 {
            let r=random(&mut seed);
            held=Some(Input { valid:true,write:r&1!=0,addr:[0,4,8,12,1,16,0x300,0x8000][((r>>1)%8) as usize],data:random(&mut seed),strb:((r>>8)&15) as u8,..Input::default() });
        }
        let i=Input { raw:(random(&mut seed)&31) as u8, ready:random(&mut seed)&3!=0,rst:n==733 || n==1733 || n==2733,..held.unwrap_or_default() };
        let accepted=t.m.commit(i); t.step(i); if accepted || i.rst { held=None; }
    }
    while held.is_some() || t.m.response.is_some() {
        let i=Input { ready:true,..held.unwrap_or_default() }; let accepted=t.m.commit(i);t.step(i);if accepted { held=None; }
    }
    t.inspect();
    for pair in t.frames.windows(2) {
        let a=&pair[0];let b=&pair[1];
        if a.i.valid && a.before["req_ready"]==0 && !a.i.rst && !b.i.rst {
            assert!(b.i.valid,"producer dropped held request");
            assert_eq!((a.i.write,a.i.addr,a.i.data,a.i.strb),(b.i.write,b.i.addr,b.i.data,b.i.strb));
        }
    }
    assert_eq!(t.tags["all_source_mask_pairs"],1024);
    assert_eq!(t.tags["all_wstrb_register_patterns"],240);
    for tag in ["disabled_capture_then_enable","repeat_not_counted","same_source_clear_collision","other_source_clear_collision","same_source_test_hardware","other_source_test_hardware","pending_old_snapshot","raw_snapshot_stall","test_excluded_from_raw"] { assert_eq!(t.tags[tag],5,"{tag}"); }
    assert_eq!(t.tags["idle_test_candidate"],16);
    assert_eq!(t.tags["held_test_and_consume_no_refill"],1);
    assert_eq!(t.tags["backpressure_accepts_hardware"],1);
    assert_eq!(t.tags["permissions_holes_aliases_with_hardware"],96);
    assert_eq!(t.tags["reset_cancels_stalled_response"],6);
    assert_eq!(t.tags["reset_beats_available_commit"],2);
    assert!(t.m.strobes.iter().flatten().all(|n| *n>0));
    assert!(t.m.hw.iter().chain(&t.m.test).chain(&t.m.collisions).all(|n| *n>0));
    assert!(t.m.raw_reads.iter().all(|n| *n>0));assert!(t.m.cancelled>=6);
    assert_eq!(t.m.accepted,t.m.consumed+t.m.cancelled);
    t
}
fn check(tb:&mut String,v:&Values,cycle:usize,phase:&str) {
    for (name,value) in v { writeln!(tb,"if ({name} !== 64'h{value:016x}) $fatal(1,\"cycle={cycle} {phase} {name} expected={value:x} got=%h\",{name});").unwrap(); }
}
fn testbench(hir:&FrozenHir,frames:&[Frame])->String {
    let top=&hir.circuit().name;
    let mut tb=String::from("module tb;reg clk=0,rst=0,req_valid=0,write=0,rsp_ready=0;reg [15:0] addr=0;reg [31:0] wdata=0;reg [3:0] wstrb=0;reg [4:0] raw_events=0;wire req_ready,rsp_valid,irq;wire [31:0] rdata;wire [1:0] error;\n");
    writeln!(tb,"{top} dut(.*);initial begin $dumpfile(\"trace.vcd\");$dumpvars(0,tb);").unwrap();
    for (n,f) in frames.iter().enumerate() {
        let i=f.i;
        writeln!(tb,"rst={};req_valid={};write={};addr=16'h{:04x};wdata=32'h{:08x};wstrb={};rsp_ready={};raw_events={};#1;",i.rst as u8,i.valid as u8,i.write as u8,i.addr,i.data,i.strb,i.ready as u8,i.raw).unwrap();
        if n!=0 {check(&mut tb,&f.before,n,"before");} tb.push_str("clk=1;#1;\n");check(&mut tb,&f.after,n,"after");tb.push_str("clk=0;#1;\n");
    }
    tb.push_str("$display(\"FR197 IRQ PASS\");$finish;end endmodule\n");tb
}
fn run(dir:&Path,tool:&str,args:&[&str],log_name:&str) {
    let log=fs::File::create(dir.join(log_name)).unwrap();
    let status=Command::new("timeout").args(["--kill-after=5s","60s",tool]).args(args).current_dir(dir).stdout(Stdio::from(log.try_clone().unwrap())).stderr(Stdio::from(log)).status().expect("GNU timeout and RTL tools required");
    let output=fs::read_to_string(dir.join(log_name)).unwrap();
    assert!(status.success(),"{tool} {args:?} failed ({status}) artifacts={}\n{output}",dir.display());
}
#[test]
#[ignore = "ATDD RED scaffold: activate during Step 05; missing Irq API expected"]
fn p0_irq_direct_rtl_independent_five_source_directed_and_seeded_oracle() {
    let hir=Irq::elaborate().unwrap();
    let design=bitloom_vlog::emit(&hir).files.iter().map(|f|f.contents.as_str()).collect::<Vec<_>>().join("\n");
    for seed in [0x1283_1970_5511,0xdead_beef_1283,0x7359_2401_ffff] {
        let t=trace(seed);
        let unique=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos();
        let dir=std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/fr197-irq").join(format!("direct-{seed:x}-{}-{unique}",std::process::id()));
        fs::create_dir_all(&dir).unwrap();fs::write(dir.join("design.v"),&design).unwrap();fs::write(dir.join("tb.sv"),testbench(&hir,&t.frames)).unwrap();
        let accounting=format!("seed={seed:x} frames={} accepted={} consumed={} cancelled={} hardware={:?} test={:?} collisions={:?} strobes={:?} raw_reads={:?} directed={:?}\n",t.frames.len(),t.m.accepted,t.m.consumed,t.m.cancelled,t.m.hw,t.m.test,t.m.collisions,t.m.strobes,t.m.raw_reads,t.tags);
        fs::write(dir.join("accounting.log"),&accounting).unwrap();
        fs::write(dir.join("commands.log"),"timeout --kill-after=5s 60s iverilog -V\ntimeout --kill-after=5s 60s vvp -V\ntimeout --kill-after=5s 60s iverilog -g2012 -s tb -o simulation design.v tb.sv\ntimeout --kill-after=5s 60s vvp simulation\n").unwrap();
        run(&dir,"iverilog",&["-V"],"iverilog-version.log");run(&dir,"vvp",&["-V"],"vvp-version.log");
        run(&dir,"iverilog",&["-g2012","-s","tb","-o","simulation","design.v","tb.sv"],"compile.log");run(&dir,"vvp",&["simulation"],"run.log");
        assert!(fs::read_to_string(dir.join("run.log")).unwrap().contains("FR197 IRQ PASS"));println!("{accounting}artifacts={}",dir.display());
    }
}
